<h1 class="h4 fw-bold mb-3">Returns &amp; replacements</h1>
<div class="table-responsive bg-white rounded-3 shadow-sm"><table class="table align-middle mb-0"><thead><tr><th>Order</th><th>Item</th><th>Type</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>
<?php foreach ($returns as $r): ?><tr><td><a href="<?= e(url('admin/orders/' . $r['order_no'])) ?>"><?= e($r['order_no']) ?></a><div class="small text-muted"><?= e($r['customer_name']) ?></div></td><td class="small"><?= e($r['item_name']) ?> ×<?= (int)$r['qty'] ?></td><td><?= e(ucfirst($r['type'])) ?></td><td class="small"><?= e($r['reason']) ?><?= $r['details'] ? '<div class="text-muted">' . e($r['details']) . '</div>' : '' ?></td><td><?= status_badge($r['status']) ?></td>
<td><?php if (in_array($r['status'], ['requested', 'approved'], true)): ?><form method="post" action="<?= e(url('admin/returns/' . $r['id'])) ?>" class="d-flex gap-1"><?= csrf_field() ?><input class="form-control form-control-sm" name="note" placeholder="Note" maxlength="250" aria-label="Note">
<?php if ($r['status'] === 'requested'): ?><button class="btn btn-sm btn-success" name="action" value="approve">Approve</button><button class="btn btn-sm btn-outline-danger" name="action" value="reject">Reject</button><?php else: ?><button class="btn btn-sm btn-dark" name="action" value="complete">Mark received</button><?php endif; ?></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$returns): ?><tr><td colspan="6" class="text-center text-muted py-4">No requests.</td></tr><?php endif; ?></tbody></table></div>
